/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Tile sizes chosen to balance cache locality and code size on a modern x64 CPU.
# TI tiles rows (i dimension), TJ tiles columns (j dimension).
TI = 32
TJ = 64

@proc
def kernel_bicg(
    m: size,
    n: size,
    A: DATA_TYPE[n, m] @ DRAM,
    s: DATA_TYPE[m] @ DRAM,
    q: DATA_TYPE[n] @ DRAM,
    p: DATA_TYPE[m] @ DRAM,
    r: DATA_TYPE[n] @ DRAM,
):
    # Local tile buffers:
    #  - q_tile accumulates partial contributions to q over a small block of rows.
    #  - s_tile accumulates partial contributions to s over a small block of columns.
    #
    # Extra memory is TI + TJ elements of DATA_TYPE, which is negligible compared
    # to the n*m elements of A and safely below the 50% overhead guideline.
    q_tile: DATA_TYPE[TI]
    s_tile: DATA_TYPE[TJ]

    # Initialize q and s to zero. The original kernel initializes s once
    # and q[i] at the start of each i-iteration; this is algebraically
    # equivalent to zeroing them fully once here and then only accumulating.
    for i in seq(0, n):
        q[i] = 0.0
    for j in seq(0, m):
        s[j] = 0.0

    # Tiled BiCG computation.
    #
    # We traverse A in 2D tiles [TI x TJ]. For each column tile J we:
    #   - use s_tile[jj] (0 <= jj < TJ) to accumulate all contributions
    #     to s[J*TJ + jj] from every row.
    # For each row tile I inside this column tile we:
    #   - use q_tile[ii] (0 <= ii < TI) to accumulate the contribution
    #     to q[I*TI + ii] from columns in the current J-tile.
    #
    # This improves cache locality for:
    #   - rows of A (contiguous in j),
    #   - slices of p and s over j in the J-tile,
    #   - small blocks of q and r over i in the I-tile.
    #
    # Boundary tiles are handled via guards (i < n, j < m) so we never
    # access out-of-bounds elements.
    for J in seq(0, (m + TJ - 1) / TJ):
        # Zero the tile-local accumulator for s over this column tile.
        for jj in seq(0, TJ):
            if J * TJ + jj < m:
                s_tile[jj] = 0.0

        for I in seq(0, (n + TI - 1) / TI):
            # Zero the tile-local accumulator for q over this row tile.
            for ii in seq(0, TI):
                if I * TI + ii < n:
                    q_tile[ii] = 0.0

            # Main micro-kernel over the current (I, J) tile.
            for ii in seq(0, TI):
                i = I * TI + ii
                if i < n:
                    # Reuse r[i] across all columns in this tile.
                    r_i = r[i]
                    for jj in seq(0, TJ):
                        j = J * TJ + jj
                        if j < m:
                            # Load A[i, j] once and reuse for both updates.
                            a_ij = A[i, j]
                            s_tile[jj] += r_i * a_ij
                            q_tile[ii] += a_ij * p[j]

            # Accumulate this tile's contribution into the global q.
            for ii in seq(0, TI):
                i = I * TI + ii
                if i < n:
                    q[i] += q_tile[ii]

        # After processing all row tiles for this column tile, accumulate
        # the tile-local s into the global s.
        for jj in seq(0, TJ):
            j = J * TJ + jj
            if j < m:
                s[j] += s_tile[jj]

# Apply a simplification pass as a (pure) scheduling transformation.
# This cleans up constant expressions and minor redundancies.
kernel_bicg = simplify(kernel_bicg)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_bicg(/*ctxt=*/NULL, m, n,
	      (DATA_TYPE*)POLYBENCH_ARRAY(A),
	      (DATA_TYPE*)POLYBENCH_ARRAY(s),
	      (DATA_TYPE*)POLYBENCH_ARRAY(q),
	      (DATA_TYPE*)POLYBENCH_ARRAY(p),
	      (DATA_TYPE*)POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}
