def kernel_bicg(
    m: size,
    n: size,
    A: DATA_TYPE[n, m] @ DRAM,
    s: DATA_TYPE[m] @ DRAM,
    q: DATA_TYPE[n] @ DRAM,
    p: DATA_TYPE[m] @ DRAM,
    r: DATA_TYPE[n] @ DRAM,
):
    # 1. Initialize s to zero over its m entries.
    #    This loop is embarrassingly parallel and has perfectly
    #    contiguous accesses to s.
    for j in seq(0, m):
        s[j] = 0.0

    # 2. Main BiCG computation: single pass over A that forms both
    #    s = A^T r and q = A p.
    #
    #    For each row i:
    #      - hoist r[i] into a scalar ri
    #      - accumulate q[i] in a scalar qi
    #      - walk j across the row of A, updating both s[j] and qi
    #
    #    This reduces memory traffic compared to repeatedly loading
    #    q[i] and r[i] from memory and exposes a clean inner loop that
    #    the C backend can autovectorize.
    for i in seq(0, n):
        ri: DATA_TYPE
        qi: DATA_TYPE

        ri = r[i]
        qi = 0.0

