from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tiling factors chosen for a modern x64 CPU. They do not depend on the
# problem sizes and are compile-time constants, so they are valid in
# Exo loop bounds and index expressions.
TILE_I: int = 32   # tile size in the row (i / n) dimension
TILE_J: int = 64   # tile size in the column (j / m) dimension


@proc
def kernel_bicg(
    m: size,
    n: size,
    A: DATA_TYPE[n, m] @ DRAM,
    s: DATA_TYPE[m] @ DRAM,
    q: DATA_TYPE[n] @ DRAM,
    p: DATA_TYPE[m] @ DRAM,
    r: DATA_TYPE[n] @ DRAM,
):
    # BiCG computes:
    #   s[j] = sum_{i=0}^{n-1} r[i] * A[i, j]   (s = A^T * r)
    #   q[i] = sum_{j=0}^{m-1} A[i, j] * p[j]   (q = A * p)
    #
    # The original kernel initializes s over its m entries, then for each
    # row i it sets q[i] = 0 and performs the fused update over j. It is
    # equivalent (up to floating-point reordering) to:
    #
    #   for j in 0..m-1: s[j] = 0
    #   for i in 0..n-1: q[i] = 0
    #   for i in 0..n-1:
    #     for j in 0..m-1:
    #       s[j] += r[i] * A[i, j]
    #       q[i] += A[i, j] * p[j]
    #
    # We use this mathematically equivalent form and then apply 2D tiling.

    # Initialize s to zero over its m entries.
    for j in seq(0, m):
        s[j] = 0.0

    # Initialize q to zero over its n entries.
    for i in seq(0, n):
        q[i] = 0.0

    # 2D tiled traversal of A, r, p that improves cache locality and
    # exposes a contiguous inner loop for the C compiler to vectorize.
    #
    # The tile loops cover the full (i, j) domain using guards to avoid
    # out-of-bounds accesses on the last (partial) tiles. Every pair
    # (i, j) with 0 <= i < n and 0 <= j < m is visited exactly once.
    for I in seq(0, (n + TILE_I - 1) // TILE_I):
        for J in seq(0, (m + TILE_J - 1) // TILE_J):
            # Tile-local loops over rows (ii) and columns (jj).
            for ii in seq(0, TILE_I):
                # Global row index for this tile.
                if TILE_I * I + ii < n:
                    for jj in seq(0, TILE_J):
                        # Global column index for this tile.
                        if TILE_J * J + jj < m:
                            s[TILE_J * J + jj] += (
                                r[TILE_I * I + ii]
                                * A[TILE_I * I + ii, TILE_J * J + jj]
                            )
                            q[TILE_I * I + ii] += (
                                A[TILE_I * I + ii, TILE_J * J + jj]
                                * p[TILE_J * J + jj]
                            )

# Apply a simple cleanup pass so the generated C is as straightforward as
# possible after tiling.
kernel_bicg = simplify(kernel_bicg)
EXO END
